"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 LLM gatekeepers (plan 6.4). This file: prompt building (shared by B2-fast, B2-strong, B2-local) and
B2-local on the laptop GPU.

Prompt = policy v2 (configs/policy_v2_prompt.txt, the full policy) + K training examples + the case, asked as plan
section 2 says: S where the assistant is talking, R where a line just ended (both where both hold). The case is the
situation text (plan 3.1, variant "full": detected sounds with scores, transcripts, speaker tags, the assistant's state
and the gold history). Examples: windows of the training set (draw 0 and episode render 0), cycled over the parts and
versions so every K covers each kind of situation (seeded); each shown with its gold answers to the questions asked.
The 24 kinds follow the plan's tables: the floor check "D, Dk" (plan 4.6, one row: a ring or a knock the user ignores)
is one kind whose examples are drawn from both its phone and its knock units.
B2-local: whisper-small transcripts (as all local systems), Qwen3.5-4B (rev 851bf6e, 4-bit NF4, bf16 compute, thinking
off). Each question is asked in its own pass ("Answer S with one word: STOP or CONTINUE." / "... R ... RESPOND or
NOT."). The score is the model's probability of its answer, P(yes words) / (P(yes words) + P(no words)) with the
capitalisations summed (plan 6.4: probabilities as scores, thresholds set on dev in its favour), read at two places of
the same pass: "first" = the first answer token (the model answers at once); "label" = after the label "S:" / "R:"
appended to the answer (the examples' format "Answers: S: STOP R: RESPOND"; the word with or without a leading space).
The reading, K in {6, 24, 48} and the thresholds are chosen on dev by the operating-point rule; a K whose prompt does
not fit the card is dropped and logged (plan 6.4). The policy + examples prefix is encoded once, in pieces of CHUNK
tokens, and its cache copied for each case (as a deployed cascade would); the first cases of every K are checked
against the same input run from a fresh cache in pieces of 512 tokens (split points unrelated to the prefix).
Changed on 2026-11-16, before B2-local's result was used (docs/iterations.md): the first run encoded the prefix in one
pass, which builds a heads x tokens x tokens float32 table in the 8 full-attention layers (1.6 GB at K = 24), so K = 24
and 48 ran out of memory and were dropped; in pieces of 1,024 tokens they fit (peak 4.5 and 5.3 GB) and the scores
equal the one-pass ones at K = 6 (scripts/p1v4_b2_memcheck.py, data/p1v4/runs/b2local_check/). With more examples the
model often writes the label first ("R: NOT": at K = 48 the label took 61% of the first token on the check case), so
the first-token reading alone mismeasured its answer; the "label" reading was added. The first run is kept in
data/p1v4/runs/b2local_first/.
Changed on 2026-11-21 (test day, amendment 2.3 bug fix, the author's choice): the cache check's limit is 0.15 instead of
0.05. The two passes round differently (4-bit weights, bf16 compute, different split points): on 93 dev questions per
K they differ by more than 0.05 on 1-10 questions per K and reading, maximum 0.093 (scripts/p1v4_b2_cache_diag.py), so
0.05 on the first 3 questions passed or failed by chance (it stopped the test run at K = 24 with 0.056). Scores are
unchanged: the check only decides whether the run goes on.
usage: python -X utf8 scripts/p1v4_b2.py local <out_dir> [limit]      (limit: first points only, for a code check)
       python -X utf8 scripts/p1v4_b2.py rechoose <out_dir>        (the choice again with the amended threshold grid)
"""
import copy
import json
import os
import random
import sys

import torch

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402

POLICY = open("configs/policy_v2_prompt.txt", encoding="utf-8").read().strip()
QWEN = ("Qwen/Qwen3.5-4B", "851bf6e806efd8d0a36b00ddf55e13ccb7b8cd0a")
QUESTION = {"S": "Answer S with one word: STOP or CONTINUE.", "R": "Answer R with one word: RESPOND or NOT."}
WORDS = {"S": (("STOP", "Stop", "stop"), ("CONTINUE", "Continue", "continue")),
         "R": (("RESPOND", "Respond", "respond"), ("NOT", "Not", "not"))}
LABEL = {"S": "S:", "R": "R:"}
READINGS = ("first", "label")
CHUNK = 1024
TYPES = [("r_hear", "1"), ("r_hear", "2"), ("r_hear", "3"), ("r_react", "1"), ("r_react", "2"), ("s_react", "1"),
         ("s_react", "2"), ("s_react", "3"), ("s_react", "4"), ("s_move", "1"), ("s_move", "2"), ("s_move", "3"),
         ("s_move", "4"), ("episode", "pickup"), ("episode", "away"), ("episode", "mid"), ("episode", "return"),
         ("episode", "control"), ("episode", "stop_or_not"), ("floor", "HE"), ("floor", "HS"), ("floor", "barge"),
         ("floor", "D"), ("floor", "quiet")]


def case_block(text, asks):
    return f"Situation:\n{text}\nQuestions: {' '.join(asks)}"


def answer_words(gold, asks):
    out = []
    for a in asks:
        q = a[0]
        if q == "S" and gold.get("S") is not None:
            out.append(f"S: {gold['S'].upper()}")
        if q == "R" and gold.get("R") is not None:
            out.append(f"R: {gold['R'].upper()}")
    return " ".join(out)


def pick_examples(K, seed=0):
    """K training windows (draw 0 and episode render 0), cycling over TYPES; each with at least one gold answer."""
    rows = D.folder_rows(os.path.join(D.RENDER, "train_d00"))
    by = {}
    for r in rows:
        for p in r["points"]:
            if r["part"] == "episode":
                key = ("episode", p.get("category"))
            elif r["part"] == "floor":
                kind = r["spec"]["which"].split("_")[0]
                key = ("floor", "D" if kind == "Dk" else kind)     # plan 4.6: "D, Dk" is one check (ring or knock)
            else:
                key = (r["part"], r["version"])
            by.setdefault(key, []).append((r, p["k"]))
    rng = random.Random(seed)
    out = []
    for i in range(K):
        out.append(rng.choice(by[TYPES[i % len(TYPES)]]))
    return out


def example_block(examples, ctx):
    parts = []
    for r, k in examples:
        text, asks = ctx.situation(r, k, "full")
        parts.append(f"{case_block(text, asks)}\nAnswers: {answer_words(r['points'][k]['gold'], asks)}")
    return "\n\n".join(parts)


def prompt(case, examples_txt):
    return f"{POLICY}\n\nExamples:\n\n{examples_txt}\n\nNow decide this case.\n{case}"


def load_qwen():
    from transformers import AutoModelForImageTextToText, AutoTokenizer, BitsAndBytesConfig
    tok = AutoTokenizer.from_pretrained(QWEN[0], revision=QWEN[1])
    lm = AutoModelForImageTextToText.from_pretrained(
        QWEN[0], revision=QWEN[1], device_map="cuda",
        quantization_config=BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_quant_type="nf4",
                                               bnb_4bit_compute_dtype=torch.bfloat16)).eval()
    return tok, lm


def answer_ids(tok):
    """{reading: {question: (yes token ids, no token ids)}}: "first" = each word's first token; "label" = the first
    token of each word with or without a leading space (it follows "S:" / "R:")."""
    out = {"first": {}, "label": {}}
    for q, groups in WORDS.items():
        out["first"][q] = tuple(sorted({tok.encode(w, add_special_tokens=False)[0] for w in ws}) for ws in groups)
        out["label"][q] = tuple(sorted({tok.encode(s + w, add_special_tokens=False)[0] for w in ws for s in ("", " ")})
                                for ws in groups)
        for rd in out:
            assert not set(out[rd][q][0]) & set(out[rd][q][1]), (rd, q)
    return out


def prefix_ids(tok, block):
    """Token ids of the policy + examples prefix (the chat-formatted prompt up to "Now decide this case.\n")."""
    marker = "Now decide this case.\n"
    full0 = tok.apply_chat_template([{"role": "user", "content": prompt("X", block) + "\nX"}],
                                    add_generation_prompt=True, enable_thinking=False, tokenize=False)
    pre_text = full0[:full0.index(marker) + len(marker)]
    return pre_text, tok(pre_text, add_special_tokens=False, return_tensors="pt").input_ids.cuda()


def question_ids(tok, case, block, q):
    """(prompt text, prompt ids + the label "S:" / "R:", number of logits to keep: the last prompt token's and the
    label's)."""
    full = tok.apply_chat_template([{"role": "user", "content": prompt(case, block) + "\n" + QUESTION[q]}],
                                   add_generation_prompt=True, enable_thinking=False, tokenize=False)
    ids = tok(full, add_special_tokens=False, return_tensors="pt").input_ids.cuda()
    lab = tok(LABEL[q], add_special_tokens=False, return_tensors="pt").input_ids.cuda()
    return full, torch.cat([ids, lab], 1), lab.shape[1] + 1


def encode_prefix(lm, pre_ids, chunk=CHUNK):
    cache = None
    for s in range(0, pre_ids.shape[1], chunk):
        e = min(s + chunk, pre_ids.shape[1])
        cache = lm(input_ids=pre_ids[:, s:e], past_key_values=cache, use_cache=True, logits_to_keep=1,
                   cache_position=torch.arange(s, e, device=pre_ids.device)).past_key_values
    return cache


def case_logits(lm, x, cache, start, keep):
    """Logits of the last `keep` positions of x, running x[start:] after a copy of the prefix cache."""
    c = copy.deepcopy(cache)
    lg = lm(input_ids=x[:, start:], past_key_values=c, use_cache=True, logits_to_keep=keep,
            cache_position=torch.arange(start, x.shape[1], device=x.device)).logits[0]
    del c
    return lg


def scratch_logits(lm, x, keep, chunk=512):
    """The same logits from a fresh cache, x in pieces of `chunk` tokens; the last piece is the last `keep` tokens."""
    n = x.shape[1]
    cuts = sorted(set(list(range(0, n - keep, chunk)) + [n - keep, n]))
    cache, lg = None, None
    for s, e in zip(cuts[:-1], cuts[1:]):
        out = lm(input_ids=x[:, s:e], past_key_values=cache, use_cache=True, logits_to_keep=keep,
                 cache_position=torch.arange(s, e, device=x.device))
        cache, lg = out.past_key_values, out.logits[0]
    return lg


def scores_of(lg, q, ids):
    """{reading: (score, probability of the answer words)}; lg[0] = the last prompt token's logits (first answer
    token), lg[-1] = the label's last token's (the word after "S:" / "R:")."""
    out = {}
    for rd, row in (("first", lg[0]), ("label", lg[-1])):
        p = row.float().softmax(-1)
        yes, no = float(p[list(ids[rd][q][0])].sum()), float(p[list(ids[rd][q][1])].sum())
        out[rd] = (yes / max(yes + no, 1e-12), yes + no)
    return out


def local(out_dir, which="dev", limit=None, quiet=None, required_K=None):
    """quiet (default: any split other than dev; freeze amendment 2.2 step 6 and 13): no operating point, choice or
    metric is computed or printed on the split; only the scores and run facts are written. required_K: the frozen K;
    if it does not fit the card the run stops with an error (other Ks are dropped and logged, plan 6.4)."""
    quiet = which != "dev" if quiet is None else quiet
    os.makedirs(out_dir, exist_ok=True)
    D.gpu_guard()                     # a K that does not fit fails with an OOM error (no spill)
    rows = D.load_rows(which)
    ctx = C.Context(which)
    tr_ctx = C.Context(None, folders=["train_d00"])           # examples come from train draw 0 only
    ex_all = pick_examples(48)
    blocks = {K: example_block(ex_all[:K], tr_ctx) for K in (6, 24, 48)}
    json.dump({"examples": [f"{r['unit']}|{r['version']}|{k}" for r, k in ex_all], "blocks": blocks},
              open(os.path.join(out_dir, "examples.json"), "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    tok, lm = load_qwen()
    ids = answer_ids(tok)
    print("answer token ids:", json.dumps(ids), flush=True)
    log, best = [], None

    def run_k(K, paths, sc):
        pre_text, pre_ids = prefix_ids(tok, blocks[K])
        L = pre_ids.shape[1]
        torch.cuda.reset_peak_memory_stats()
        with torch.no_grad():
            cache = encode_prefix(lm, pre_ids)
        checks, n_uncached, n_tok = [], 0, None
        n, masses = 0, {rd: [] for rd in READINGS}
        for r in rows:
            for p in r["points"]:
                key = f"{r['unit']}|{r['version']}|{p['k']}"
                if all(key in sc[rd] for rd in READINGS):
                    continue
                if limit is not None and n >= limit:
                    break
                text, asks = ctx.situation(r, p["k"], "full")
                case = case_block(text, asks)
                d = {rd: {} for rd in READINGS}
                for a in asks:
                    q = a[0]
                    full, x, keep = question_ids(tok, case, blocks[K], q)
                    n_tok = x.shape[1]
                    with torch.no_grad():
                        if full.startswith(pre_text) and torch.equal(x[0, :L], pre_ids[0]):
                            lg = case_logits(lm, x, cache, L, keep)
                        else:
                            lg = scratch_logits(lm, x, keep)
                            n_uncached += 1
                        res = scores_of(lg, q, ids)
                        if len(checks) < 3:
                            ref = scores_of(scratch_logits(lm, x, keep), q, ids)
                            checks.append(max(abs(ref[rd][0] - res[rd][0]) for rd in READINGS))
                            assert checks[-1] < 0.15, f"cached and fresh scores differ: {ref} vs {res}"
                    for rd in READINGS:
                        d[rd][q] = res[rd][0]
                        masses[rd].append(res[rd][1])
                for rd in READINGS:
                    sc[rd][key] = d[rd]
                n += 1
                if n % 200 == 0:
                    for rd in READINGS:
                        json.dump(sc[rd], open(paths[rd], "w"))
                    print(f"K={K}: {len(sc['first'])} points (prompt {n_tok} tokens; P(answer words) first "
                          f"{masses['first'][-1]:.3f}, label {masses['label'][-1]:.3f}; "
                          f"peak {torch.cuda.max_memory_allocated() / 2**30:.1f} GB)", flush=True)
        for rd in READINGS:
            json.dump(sc[rd], open(paths[rd], "w"))
        del cache
        info = {"prefix_tokens": L, "prompt_tokens_last": n_tok, "peak_gb": torch.cuda.max_memory_allocated() / 2**30,
                "cache_check_max_diff": max(checks) if checks else None, "uncached_cases": n_uncached}
        for rd in READINGS:
            m = sorted(masses[rd])
            info[f"answer_word_mass_{rd}"] = {"min": m[0], "median": m[len(m) // 2]} if m else None
        return info

    for K in (6, 24, 48):
        paths = {rd: os.path.join(out_dir, f"scores_{which}_K{K}_{rd}.json") for rd in READINGS}
        sc = {rd: json.load(open(paths[rd])) if os.path.exists(paths[rd]) else {} for rd in READINGS}
        try:
            info = run_k(K, paths, sc)
        except torch.cuda.OutOfMemoryError:              # plan 6.4: a K that does not fit the card is dropped
            if required_K is not None and K == required_K:
                raise SystemExit(f"B2-local: the frozen K={K} does not fit the card on {which} (CUDA out of memory); "
                                 f"the decision table needs it: stop and investigate")
            log.append({"K": K, "dropped": "does not fit the 8 GB card (CUDA out of memory)"})
            print("WARNING:", json.dumps(log[-1]), flush=True)
            torch.cuda.empty_cache()
            continue
        print(json.dumps({"K": K, **info}), flush=True)
        if limit is not None or quiet:                   # code check, or a final split: no operating point here
            log.append({"K": K, **info})
            torch.cuda.empty_cache()
            continue
        for rd in READINGS:
            scores = {tuple(k.split("|")[:2]) + (int(k.split("|")[2]),): v for k, v in sc[rd].items()}
            res = S.operating_point(rows, scores)
            res.update(K=K, reading=rd, **info)
            log.append(res)
            print(json.dumps({k: res[k] for k in ("K", "reading", "th_s", "th_r", "floors_met", "primary",
                                                  "lowest_floor", "floors", "parts")}), flush=True)
            rank = (res["floors_met"], res["primary"], res["lowest_floor"])
            if best is None or rank > best[0]:
                best = (rank, K, rd)
        torch.cuda.empty_cache()
    json.dump({"log": log, "chosen_K": best[1] if best else None, "chosen_reading": best[2] if best else None},
              open(os.path.join(out_dir, f"b2local_{which}.json"), "w"), indent=1)
    print("chosen", best[1:] if best else None)


def rechoose(out_dir, which="dev"):
    """The operating-point rule again on the stored scores of every K and reading, with the current threshold grid
    (p1v4_score.GRID, amended 2026-11-16). The earlier choice file is kept as b2local_<which>_grid005.json; the
    earlier log's run facts (prefix tokens, peak memory, checks) are carried over."""
    rows = D.load_rows(which)
    path = os.path.join(out_dir, f"b2local_{which}.json")
    old = json.load(open(path))
    keep = os.path.join(out_dir, f"b2local_{which}_grid005.json")
    if not os.path.exists(keep):
        json.dump(old, open(keep, "w"), indent=1)
    log, best = [], None
    for K in (6, 24, 48):
        for rd in READINGS:
            p = os.path.join(out_dir, f"scores_{which}_K{K}_{rd}.json")
            if not os.path.exists(p):
                continue
            sc = {tuple(k.split("|")[:2]) + (int(k.split("|")[2]),): v for k, v in json.load(open(p)).items()}
            res = S.operating_point(rows, sc)
            prev = next((e for e in old["log"] if e.get("K") == K and e.get("reading") == rd), {})
            res.update({k: v for k, v in prev.items() if k not in res})
            res.update(K=K, reading=rd)
            log.append(res)
            print(json.dumps({k: res[k] for k in ("K", "reading", "th_s", "th_r", "floors_met", "primary",
                                                  "lowest_floor")}), flush=True)
            rank = (res["floors_met"], res["primary"], res["lowest_floor"])
            if best is None or rank > best[0]:
                best = (rank, K, rd)
    json.dump({"log": log, "chosen_K": best[1] if best else None, "chosen_reading": best[2] if best else None},
              open(path, "w"), indent=1)
    print("chosen", best[1:] if best else None)


if __name__ == "__main__":
    if sys.argv[1] == "local":
        local(sys.argv[2], limit=int(sys.argv[3]) if len(sys.argv) > 3 else None)
    elif sys.argv[1] == "rechoose":
        rechoose(sys.argv[2])
    else:
        raise SystemExit(__doc__)
